        if nr:
            final.append(nr)

    for c in customers:
        if c not in seen:
            dc = demand(c)
            placed = False
            for r in final:
                if load_of(r) + dc <= cap:
                    r.append(c)
                    placed = True
                    break
            if not placed:
                final.append([c])

    final = [two_opt(r) for r in final if r]
    return final
